import {SKILLS,overall,starters,getPlayer,familiarity,historicalStandings,rng} from './engine.js';
import {beginOffseason} from './market.js';
export function ensureCareer(s){if(!s.career)s.career={stints:[{team:s.team,start:0,end:null,year:s.results[0]?.year||s.year}],peaks:{skills:{}},service:{},jobs:null};s.career.peaks.skills??={};s.career.service??={};return s.career;}
export function recordCareer(s){const c=ensureCareer(s),snap=p=>({id:p.id,name:p.name,portrait:p.portrait,team:s.team,year:s.year});for(const p of s.players.filter(p=>p.team===s.team)){if(!c.peaks.overall||overall(p)>c.peaks.overall.value)c.peaks.overall={...snap(p),value:overall(p)};for(const k of SKILLS)if(!c.peaks.skills[k]||p.skills[k]>c.peaks.skills[k].value)c.peaks.skills[k]={...snap(p),value:p.skills[k]};const key=s.team+':'+p.id;let x=c.service[key];if(!x)x=c.service[key]={...snap(p),since:s.year,firstStep:s.step,weeks:0,lastStep:s.step};x.weeks+=Math.max(0,s.step-x.lastStep);x.lastStep=s.step;x.name=p.name;}
 for(const x of Object.values(c.service))if(x.team!==s.team||getPlayer(s,x.id)?.team!==s.team)x.lastStep=s.step;
 const ps=starters(s);for(let i=0;i<ps.length;i++)for(let j=i+1;j<ps.length;j++){const value=familiarity(s,ps[i].id,ps[j].id);if(!c.peaks.duo||value>c.peaks.duo.value)c.peaks.duo={ids:[ps[i].id,ps[j].id],names:[ps[i].name,ps[j].name],team:s.team,year:s.year,value};}return c;}
export function careerStats(s){const c=ensureCareer(s),results=s.results.filter((r,i)=>c.stints.some(t=>i>=t.start&&(t.end===null||i<t.end)&&(r.a===t.team||r.b===t.team))),mvps={},appearances={},duos={};let wins=0,gameWins=0,games=0,streak=0,longestStreak=0,bestMatch=null;
 for(const r of results){const i=s.results.indexOf(r),t=c.stints.find(t=>i>=t.start&&(t.end===null||i<t.end)&&(r.a===t.team||r.b===t.team)).team;const won=r.winner===t;wins+=+won;streak=won?streak+1:0;longestStreak=Math.max(streak,longestStreak);for(const g of r.games||[]){games++;gameWins+=+(g.winner===t);const rows=(g.ratings||[]).filter(p=>p.team===t);for(const p of rows){appearances[p.id]={id:p.id,name:p.name,count:(appearances[p.id]?.count||0)+1};if(!bestMatch||p.rating>bestMatch.value)bestMatch={...p,value:p.rating,year:r.year};if(p.id===g.mvp)mvps[p.id]={id:p.id,name:p.name,count:(mvps[p.id]?.count||0)+1};}for(let a=0;a<rows.length;a++)for(let b=a+1;b<rows.length;b++){const pair=[rows[a],rows[b]].sort((a,b)=>a.id.localeCompare(b.id)),key=pair.map(p=>p.id).join('|'),d=duos[key]??={names:pair.map(p=>p.name),games:0,wins:0};d.games++;d.wins+=+(g.winner===t);}}}
 const titles=s.honors.filter(h=>h.managerTeam!==undefined?h.winner===h.managerTeam:c.stints.some(t=>h.winner===t.team&&h.year>=t.year&&(t.endYear===undefined||h.year<=t.endYear)));
 const sorted=Object.values(mvps).sort((a,b)=>b.count-a.count||a.name.localeCompare(b.name));return {series:results.length,wins,losses:results.length-wins,games,gameWins,gameLosses:games-gameWins,winRate:results.length?wins/results.length*100:0,longestStreak,titles,worlds:titles.filter(h=>h.event==='Worlds').length,msi:titles.filter(h=>h.event==='MSI').length,regional:titles.filter(h=>!['MSI','Worlds'].includes(h.event)).length,mvps:sorted,mostPlayed:Object.values(appearances).sort((a,b)=>b.count-a.count)[0],bestMatch,bestDuo:Object.values(duos).filter(d=>d.games>=10).sort((a,b)=>b.wins/b.games-a.wins/a.games||b.games-a.games)[0],longestTenure:Object.values(c.service).sort((a,b)=>b.weeks-a.weeks||a.since-b.since)[0],peaks:c.peaks};}
export function reviewManager(s){const c=ensureCareer(s);if(c.jobs?.year===s.year)return c.jobs;const matches=s.results.filter(r=>r.year===s.year&&r.phase==='regular'&&(r.a===s.team||r.b===s.team)),wins=matches.filter(r=>r.winner===s.team).length,rate=wins/Math.max(1,matches.length),region=s.teams[s.team].region;const rows=historicalStandings(s,region,'Summer'),last=rows.at(-1)?.id===s.team;const eligible=matches.length>=10&&rate<.2&&last;const fired=eligible&&rng(s)<.08;const candidates=s.teams.filter(t=>t.id!==s.team).map(t=>({team:t.id,score:Math.abs((t.reputation||50)-(40+rate*50))+rng(s)*20})).sort((a,b)=>a.score-b.score).slice(0,3);c.jobs={year:s.year,from:s.team,fired,status:fired?'dismissed':'open',eligible,rate,offers:candidates.map(x=>({team:x.team,reason:rate>=.6?'Build a title contender':rate>=.35?'Bring a fresh approach':'Lead a rebuilding project'}))};return c.jobs;}
export const managerDecisionPending=s=>!!s.career?.jobs?.fired&&s.career.jobs.status==='dismissed';
export function stayManager(s){const j=s.career?.jobs;if(s.phase!=='offseason'||!j||j.fired||!['open'].includes(j.status))return false;j.status='stayed';return true;}
export function acceptManagerJob(s,team){const c=ensureCareer(s),j=c.jobs;if(s.phase!=='offseason'||s.market.window?.stage!=='review'||s.match||s.clubEvent||s.celebration||!j||!['open','dismissed'].includes(j.status)||!j.offers.some(o=>o.team===team))return false;recordCareer(s);const old=s.team;c.stints.at(-1).end=s.results.length;c.stints.at(-1).endYear=s.year;s.teams[old].funds=s.budget;s.budget=s.teams[team].funds;s.team=team;c.stints.push({team,start:s.results.length,end:null,year:s.year+1});j.status='accepted';j.accepted=team;for(const o of s.market.offers)if(['waiting','counter','agreed'].includes(o.status))o.status='withdrawn';for(const d of s.market.inbox)if(['incoming','counter','agreed'].includes(d.status))d.status='declined';s.market.shortlist=[];s.scouting=[];s.clubEvent=null;s.reportBaseline=Object.fromEntries(s.players.filter(p=>p.team===team).map(p=>[p.id,{...p.skills}]));s.reportStart=s.step;s.market.window=null;beginOffseason(s);s.news.unshift(`${s.manager} joins ${s.teams[team].name} for ${s.year+1}. Your career records travel with you.`);recordCareer(s);return true;}
